"""Embeds tools/seed/seed-data.json and preview/demo_content.json into
preview/demo_content.g.dart so the demo build works offline on any platform.

    python3 preview/tool/embed_demo_content.py
"""
import json
import os

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))


def compact(path):
    with open(os.path.join(ROOT, path), encoding='utf-8') as f:
        text = json.dumps(json.load(f), ensure_ascii=False, separators=(',', ':'))
    assert "'''" not in text
    return text


dart = (
    '// GENERATED by preview/tool/embed_demo_content.py — do not edit.\n'
    '// ignore_for_file: lines_longer_than_80_chars\n\n'
    "const String kSeedJson = r'''" + compact('tools/seed/seed-data.json') + "''';\n\n"
    "const String kDemoContentJson = r'''" + compact('preview/demo_content.json') + "''';\n"
)
with open(os.path.join(ROOT, 'preview', 'demo_content.g.dart'), 'w', encoding='utf-8') as f:
    f.write(dart)
print('wrote preview/demo_content.g.dart')
